    current = record
    previous = old if event == "UPDATE" and old is not None else {}

    # ACC-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_length(_value(current, "ACCT_NM")) >= 2):
            errors.append({
                "code": "E1001",
                "message": "Account name too short",
                "severity": "BLOCK",
            })

    # ACC-002: INSERT, UPDATE
