        if _value(current, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append({
                "code": "E1002",
                "message": "Invalid account type",
                "severity": "BLOCK",
            })

    # ACC-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(_value(current, "ANN_REV"), 0)) >= Decimal("0")):
            errors.append({
                "code": "E1003",
                "message": "Annual revenue negative",
                "severity": "BLOCK",
            })

    # ACC-004: UPDATE only
    if event == "UPDATE":
        condition = (
            _value(previous, "CRED_HOLD") == "Y"
            and _value(current, "CRED_HOLD") == "N"
            and _number(_value(current, "CRED_LIMIT")) <= Decimal("0")
        )
        if condition:
            errors.append({
                "code": "E1004",
                "message": "Cannot release credit hold with zero credit limit",
                "severity": "BLOCK",
            })

    # ACC-005: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_length(_value(current, "REGION_CD")) == 3):
            errors.append({
                "code": "E1005",
                "message": "Region code must be 3 chars",
                "severity": "WARN",
            })

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
